begin;
create temp table ids(name text primary key,id uuid default gen_random_uuid());
insert into ids(name) values('owner'),('viewer'),('other'),('company'),('elsewhere'),('batch'),('batch2'),('job1'),('job2'),('foreignjob');
grant select,insert,update on ids to authenticated,service_role;
create function pg_temp.id(text) returns uuid language sql as $$select id from ids where name=$1$$;
create temp table results(name text,passed boolean);
grant insert,select on results to authenticated,service_role;
create function pg_temp.ok(name text,passed boolean) returns void language plpgsql as $$begin
 if passed is distinct from true then raise exception 'FAILED: %',name;end if;insert into results values(name,true);end$$;
create function pg_temp.denied(name text,statement text) returns void language plpgsql as $$begin
 begin execute statement;exception when others then insert into results values(name,true);return;end;
 raise exception 'FAILED unexpectedly allowed: %',name;end$$;
insert into auth.users(id,email,email_confirmed_at,role,aud) select id,id::text||'@versions-test.invalid',now(),'authenticated','authenticated' from ids where name in ('owner','viewer','other');
insert into public.companies(id,name) values(pg_temp.id('company'),'Versions test'),(pg_temp.id('elsewhere'),'Other');
insert into public.company_members values(pg_temp.id('company'),pg_temp.id('owner'),'owner',now()),(pg_temp.id('company'),pg_temp.id('viewer'),'viewer',now()),(pg_temp.id('elsewhere'),pg_temp.id('other'),'owner',now());
insert into public.resume_batches(id,company_id,uploaded_by,source,file_count) values(pg_temp.id('batch'),pg_temp.id('company'),pg_temp.id('owner'),'email',5),(pg_temp.id('batch2'),pg_temp.id('elsewhere'),pg_temp.id('other'),'email',5);
insert into public.jobs(id,company_id,titulo) values(pg_temp.id('job1'),pg_temp.id('company'),'Analista'),(pg_temp.id('job2'),pg_temp.id('company'),'Supervisor'),(pg_temp.id('foreignjob'),pg_temp.id('elsewhere'),'Outra empresa');
select set_config('request.jwt.claims',json_build_object('sub',pg_temp.id('owner'),'role','authenticated')::text,true);
set local role service_role;
select set_config('test.first',public.reserve_resume_version(pg_temp.id('owner'),pg_temp.id('company'),pg_temp.id('batch'),0,repeat('a',64),'resume.pdf','application/pdf',10,1)::text,true);
insert into ids(name,id) values('person',(current_setting('test.first')::jsonb->>'candidateId')::uuid),('doc1',(current_setting('test.first')::jsonb->>'documentId')::uuid);
select public.finish_resume_upload(pg_temp.id('owner'),pg_temp.id('company'),pg_temp.id('doc1'),(current_setting('test.first')::jsonb->>'token')::uuid);
select set_config('test.second',public.reserve_resume_version(pg_temp.id('owner'),pg_temp.id('company'),pg_temp.id('batch'),1,repeat('b',64),'resume.pdf','application/pdf',11,1,pg_temp.id('person'))::text,true);
insert into ids(name,id) values('doc2',(current_setting('test.second')::jsonb->>'documentId')::uuid);
select public.finish_resume_upload(pg_temp.id('owner'),pg_temp.id('company'),pg_temp.id('doc2'),(current_setting('test.second')::jsonb->>'token')::uuid);
select pg_temp.ok('same name different bytes creates two versions of one person',(select count(*)=2 and count(distinct object_path)=2 and max(version)=2 from public.resume_documents where candidate_id=pg_temp.id('person')) and (select count(*)=1 from public.candidates where company_id=pg_temp.id('company')));
select pg_temp.ok('renamed identical bytes reuse document',public.reserve_resume_version(pg_temp.id('owner'),pg_temp.id('company'),pg_temp.id('batch'),2,repeat('b',64),'renamed.pdf','application/pdf',11,1,pg_temp.id('person'))->>'documentId'=pg_temp.id('doc2')::text);
select pg_temp.ok('latest accepted version is selected',(select active_document_id=pg_temp.id('doc2') from public.candidates where id=pg_temp.id('person')));
select pg_temp.denied('stored identity cannot be overwritten',$q$update public.resume_documents set sha256=repeat('f',64) where id=pg_temp.id('doc1')$q$);
select pg_temp.denied('foreign company cannot receive new version',$q$select public.reserve_resume_version(pg_temp.id('other'),pg_temp.id('elsewhere'),pg_temp.id('batch2'),0,repeat('c',64),'resume.pdf','application/pdf',11,1,pg_temp.id('person'))$q$);
select set_config('test.other',public.reserve_resume_version(pg_temp.id('other'),pg_temp.id('elsewhere'),pg_temp.id('batch2'),0,repeat('a',64),'resume.pdf','application/pdf',10,1)::text,true);
select pg_temp.ok('identical bytes across companies do not reveal or reuse identity',current_setting('test.other')::jsonb->>'candidateId'<>pg_temp.id('person')::text);
select count(*) from public.claim_resume_jobs();
select public.settle_resume_job(id,lease_token,'succeeded','{"nome_completo":"Old AI","email":"old@example.test","skills":["Java"]}') from public.resume_jobs where document_id=pg_temp.id('doc1');
select pg_temp.ok('old version result cannot overwrite active person',(select dados_extraidos='{}'::jsonb from public.candidates where id=pg_temp.id('person')));
select pg_temp.ok('old extraction remains attached to its document',(select latest_extraction->>'nome_completo'='Old AI' from public.resume_documents where id=pg_temp.id('doc1')));
select public.settle_resume_job(id,lease_token,'succeeded','{"nome_completo":"New AI","email":"person@example.test","telefone":"11912345678","skills":["Excel"]}') from public.resume_jobs where document_id=pg_temp.id('doc2');
select pg_temp.ok('active extraction updates person',(select nome='New AI' and skills=array['Excel'] from public.candidates where id=pg_temp.id('person')));
reset role;
insert into public.candidates(company_id,dados_extraidos,processing_status) values
 (pg_temp.id('company'),'{"nome_completo":"Same name only","email":"distinct@example.test"}','concluido'),
 (pg_temp.id('company'),'{"nome_completo":"New AI","email":"namesake@example.test"}','concluido');
with added as (insert into public.candidates(company_id,dados_extraidos,processing_status) values(pg_temp.id('company'),'{"nome_completo":"Existing person","email":"PERSON@example.test","telefone":"(11) 91234-5678"}','concluido') returning id)
insert into ids(name,id) select 'target',id from added;
-- Real original rows, without calling an AI provider.
insert into storage.objects(bucket_id,name,created_at) select 'resumes',object_path,now()-interval '2 hours' from public.resume_documents where candidate_id=pg_temp.id('person');
set local role authenticated;
select pg_temp.ok('only exact contacts suggest identity, names do not',(select count(*)=1 and bool_and(candidate_id=pg_temp.id('target')) from public.suggest_candidate_duplicates(pg_temp.id('company'),pg_temp.id('person'))));
select pg_temp.ok('both normalized contacts explain suggestion',(select reasons=array['E-mail idêntico','Telefone idêntico'] from public.suggest_candidate_duplicates(pg_temp.id('company'),pg_temp.id('person'))));
select pg_temp.denied('client cannot move document between people',$q$update public.resume_documents set candidate_id=pg_temp.id('target') where id=pg_temp.id('doc1')$q$);
select pg_temp.denied('selection requires current review version',$q$select public.select_candidate_document(pg_temp.id('company'),pg_temp.id('person'),pg_temp.id('doc1'),-1)$q$);
select public.save_candidate_review(pg_temp.id('company'),pg_temp.id('person'),(select review_version from public.candidates where id=pg_temp.id('person')),'{"nome_completo":"Human name"}',false,false);
select public.select_candidate_document(pg_temp.id('company'),pg_temp.id('person'),pg_temp.id('doc1'),(select review_version from public.candidates where id=pg_temp.id('person')));
select pg_temp.ok('selecting previous version restores extraction and preserves human correction',(select dados_extraidos->>'nome_completo'='Old AI' and nome='Human name' and review_status='pending' from public.candidates where id=pg_temp.id('person')));
select pg_temp.ok('version selection has actor audit',(select count(*)=1 from public.candidate_document_events where candidate_id=pg_temp.id('person') and action='selected' and actor_id=pg_temp.id('owner')));
select pg_temp.ok('both historical originals remain readable',(select count(*)=2 from storage.objects where bucket_id='resumes'));
select public.set_candidate_job_link(pg_temp.id('company'),pg_temp.id('person'),pg_temp.id('job1'),true);
select public.set_candidate_job_link(pg_temp.id('company'),pg_temp.id('person'),pg_temp.id('job2'),true);
select public.set_candidate_job_link(pg_temp.id('company'),pg_temp.id('person'),pg_temp.id('job1'),true);
select pg_temp.ok('explicit multiple job links are idempotent',(select count(*)=2 from public.candidate_job_links) and (select count(*)=2 from public.candidate_link_events));
select pg_temp.denied('cannot associate foreign job',$q$select public.set_candidate_job_link(pg_temp.id('company'),pg_temp.id('person'),pg_temp.id('foreignjob'),true)$q$);
select public.set_candidate_job_link(pg_temp.id('company'),pg_temp.id('person'),pg_temp.id('job2'),false);
select pg_temp.ok('withdrawing preserves person and audit',(select not active from public.candidate_job_links where job_id=pg_temp.id('job2')) and exists(select 1 from public.candidates where id=pg_temp.id('person')));
select public.set_candidate_job_link(pg_temp.id('company'),pg_temp.id('person'),pg_temp.id('job2'),true);
reset role;
update public.jobs set status='encerrada' where id=pg_temp.id('job2');
set local role authenticated;
select pg_temp.ok('search immediately sees human corrections',(select count(*)=1 from public.search_candidates(pg_temp.id('company'),'Human name')));
insert into ids(name,id) values('retry',public.request_document_analysis(pg_temp.id('company'),pg_temp.id('doc2'),gen_random_uuid()));
select pg_temp.denied('merge waits for in-flight document jobs',$q$select public.confirm_candidate_merge(pg_temp.id('company'),pg_temp.id('person'),pg_temp.id('target'),(select review_version from public.candidates where id=pg_temp.id('person')),(select review_version from public.candidates where id=pg_temp.id('target')),'Verified synthetic original documents',true)$q$);
select public.control_resume_job(pg_temp.id('company'),pg_temp.id('retry'),'cancel');
select pg_temp.ok('cancelling another version does not change active processing',(select processing_status='concluido' from public.candidates where id=pg_temp.id('person')));
select pg_temp.denied('merge requires explicit confirmation',$q$select public.confirm_candidate_merge(pg_temp.id('company'),pg_temp.id('person'),pg_temp.id('target'),0,0,'Verified synthetic original documents',false)$q$);
select pg_temp.denied('merge rejects stale review versions',$q$select public.confirm_candidate_merge(pg_temp.id('company'),pg_temp.id('person'),pg_temp.id('target'),-1,-1,'Verified synthetic original documents',true)$q$);
select public.confirm_candidate_merge(pg_temp.id('company'),pg_temp.id('person'),pg_temp.id('target'),(select review_version from public.candidates where id=pg_temp.id('person')),(select review_version from public.candidates where id=pg_temp.id('target')),'Verified synthetic original documents',true);
select pg_temp.ok('merge transfers both versions without overwriting paths',(select count(*)=2 from public.resume_documents where candidate_id=pg_temp.id('target')) and (select count(*)=2 from storage.objects));
select pg_temp.ok('analysis ownership follows documents',(select bool_and(candidate_id=pg_temp.id('target')) from public.resume_jobs where document_id in(pg_temp.id('doc1'),pg_temp.id('doc2'))));
select pg_temp.ok('merge preserves old corrections and actor',(select source_snapshot->'correcoes_rh'->>'nome_completo'='Human name' and actor_id=pg_temp.id('owner') and jsonb_array_length(source_revisions)>0 from public.candidate_merges));
select pg_temp.ok('merge keeps destination data and reopens review',(select nome='Existing person' and review_status='pending' from public.candidates where id=pg_temp.id('target')));
select pg_temp.ok('merged source leaves search',(select count(*)=0 from public.search_candidates(pg_temp.id('company'),'Human name')));
select pg_temp.ok('merge moves active job link',(select active from public.candidate_job_links where candidate_id=pg_temp.id('target') and job_id=pg_temp.id('job1')));
select pg_temp.ok('merge preserves participation in closed jobs',(select active from public.candidate_job_links where candidate_id=pg_temp.id('target') and job_id=pg_temp.id('job2')));
select pg_temp.ok('merge keeps document provenance and relationship audit',(select jsonb_array_length(source_relationships->'documentos')=2 and jsonb_array_length(source_relationships->'eventos_vagas')=4 from public.candidate_merges));
select pg_temp.ok('repeat confirmed merge is idempotent',public.confirm_candidate_merge(pg_temp.id('company'),pg_temp.id('person'),pg_temp.id('target'),-1,-1,'Verified synthetic original documents',true)=pg_temp.id('target'));
reset role;
set local role service_role;
select pg_temp.ok('cleanup never removes historical version originals',(select count(*)=0 from public.claim_resume_cleanup(pg_temp.id('owner'),pg_temp.id('company'))));
reset role;
select set_config('request.jwt.claims',json_build_object('sub',pg_temp.id('viewer'),'role','authenticated')::text,true);
set local role authenticated;
select pg_temp.denied('viewer cannot link jobs',$q$select public.set_candidate_job_link(pg_temp.id('company'),pg_temp.id('target'),pg_temp.id('job2'),true)$q$);
select pg_temp.denied('viewer cannot select version',$q$select public.select_candidate_document(pg_temp.id('company'),pg_temp.id('target'),pg_temp.id('doc1'),0)$q$);
reset role;
select set_config('request.jwt.claims',json_build_object('sub',pg_temp.id('other'),'role','authenticated')::text,true);
set local role authenticated;
select pg_temp.ok('foreign company cannot see links history or originals',(select count(*)=0 from public.candidate_job_links) and (select count(*)=0 from public.candidate_merges) and (select count(*)=0 from storage.objects));
select pg_temp.ok('foreign company cannot search people',(select count(*)=0 from public.search_candidates(pg_temp.id('company'),'')));
select pg_temp.ok('foreign company cannot enumerate duplicate contacts',(select count(*)=0 from public.suggest_candidate_duplicates(pg_temp.id('company'),pg_temp.id('target'))));
reset role;
insert into public.candidates(company_id,dados_extraidos) select pg_temp.id('company'),jsonb_build_object('nome_completo','Search fixture '||n) from generate_series(1,1100) n;
select set_config('request.jwt.claims',json_build_object('sub',pg_temp.id('owner'),'role','authenticated')::text,true);
set local role authenticated;
select pg_temp.ok('search finds a person beyond the first thousand',(select count(*)=1 from public.search_candidates(pg_temp.id('company'),'Search fixture 1100')));
select pg_temp.ok('search pagination reaches the whole authorized pool',(select count(*)=51 from public.search_candidates(pg_temp.id('company'),'Search fixture','todos',1000)));
reset role;
select json_build_object('passed',count(*),'tests',json_agg(name)) as results from results;
rollback;
